  using System.Runtime.InteropServices
  {
      [DllImport("WindowsAPI.h")]
      static int SetServiceStatus(int serviceId, bool bEnabled)
      {
          return SetServiceStatus(0x2, bEnabled)
      }
      // serviceId: e.g. 2 for Microsoft Defender (may vary)
